CREATE TABLE reading_books (
 id VARCHAR(66) PRIMARY KEY, slug VARCHAR(80) NOT NULL UNIQUE,
 name VARCHAR(100) NOT NULL, title VARCHAR(200) NOT NULL, author VARCHAR(200) NOT NULL,
 cover VARCHAR(300) NOT NULL, categories VARCHAR(100) NOT NULL,
 tone VARCHAR(7) NOT NULL, accent VARCHAR(7) NOT NULL,
 challenge_enabled BOOLEAN NOT NULL, sort_order INTEGER NOT NULL
);
CREATE TABLE reading_tasks (
 id VARCHAR(80) PRIMARY KEY, book_id VARCHAR(66) NOT NULL,
 task_index INTEGER NOT NULL, title VARCHAR(100) NOT NULL, card VARCHAR(2000) NOT NULL,
 question VARCHAR(300) NOT NULL, option_zero VARCHAR(300) NOT NULL,
 option_one VARCHAR(300) NOT NULL, option_two VARCHAR(300) NOT NULL,
 answer INTEGER NOT NULL, UNIQUE(book_id, task_index),
 FOREIGN KEY (book_id) REFERENCES reading_books(id)
);
ALTER TABLE reading_submissions ADD COLUMN book_id VARCHAR(66);
ALTER TABLE reading_submissions ADD COLUMN contract_address VARCHAR(42);
ALTER TABLE reading_submissions ADD COLUMN answer INTEGER;
