INSERT INTO reading_books VALUES ('0x6609f0af34e0978b4b6274f731bb1b2769335f2f705598d2a95234700ec081c5','naval-almanack-v1','纳瓦尔宝典','The Almanack of Naval Ravikant','Eric Jorgenson','/readpact/books/naval.jpg','ideas,business','#eee8dc','#3d3527', TRUE, 15);
INSERT INTO reading_tasks VALUES ('0x6609f0af34e0978b4b6274f731bb1b2769335f2f705598d2a95234700ec081c5:0','0x6609f0af34e0978b4b6274f731bb1b2769335f2f705598d2a95234700ec081c5',0,'长期主义','长期合作能让信任和经验不断积累。做一次交易只看当下收益，反复合作还要考虑声誉和未来。今天请想一想：在工作或生活中，哪一种关系值得你投入更长时间？（原创共读引导，非原书引文。）','根据卡片，反复合作为什么需要考虑声誉？','因为只要一次获得最多收益就足够','因为信任会影响未来的持续合作','因为声誉可以替代实际行动',1);
INSERT INTO reading_tasks VALUES ('0x6609f0af34e0978b4b6274f731bb1b2769335f2f705598d2a95234700ec081c5:1','0x6609f0af34e0978b4b6274f731bb1b2769335f2f705598d2a95234700ec081c5',1,'专长','专长往往来自持续的好奇心和个人经历，而不只是人人都能完成的标准训练。找到你愿意主动探索、不断练习的事情，再用真实问题检验它。今天请写下自己愿意长期研究的一件事。（原创共读引导，非原书引文。）','根据卡片，探索个人专长更适合从哪里开始？','只追逐所有人都在学的热门技能','从持续的好奇心与个人经历出发','只选择短期回报最高的事情',1);
INSERT INTO reading_tasks VALUES ('0x6609f0af34e0978b4b6274f731bb1b2769335f2f705598d2a95234700ec081c5:2','0x6609f0af34e0978b4b6274f731bb1b2769335f2f705598d2a95234700ec081c5',2,'复利','复利不只发生在金钱上，也发生在知识、信任和技能上。一次小积累未必显眼，持续积累才可能放大效果；频繁推倒重来会中断积累。今天请选择一个足够小、能够长期坚持的阅读行动。（原创共读引导，非原书引文。）','根据卡片，什么更有利于知识和技能的复利？','每天换一个完全无关的目标','在同一方向持续做小幅积累','等有整块空闲时间再开始',1);
